{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 7,
      "text_ar": "بعد سبعة أيام، العالم الذي لم يستيقظ بعد سيقام، وما هو قابل للفساد سيموت.",
      "verse": 31
    },
    {
      "chapter": 7,
      "text_ar": "سترد الأرض أولئك الراقدين فيها، والتراب أولئك الساكنين فيه في سكوت، والأماكن السرية ستسلم تلك النفوس التي سلمت إليها.",
      "verse": 32
    },
    {
      "chapter": 7,
      "text_ar": "العلي سيعلن على كرسي الدينونة، والرحمة ستزول، والصبر سيسحب.",
      "verse": 33
    },
    {
      "chapter": 7,
      "text_ar": "الدينونة وحدها ستبقى. الحق سيقف. الإيمان سيقوى.",
      "verse": 34
    },
    {
      "chapter": 7,
      "text_ar": "المجازاة ستتبع. المكافأة ستظهر. الأعمال الصالحة ستستيقظ، والأعمال الشريرة لن تنام.",
      "verse": 35
    }
  ]
}
